// Isolated component harness only: every state, price and billing callback is fictional.
import React,{useState} from 'react';import{createRoot}from'react-dom/client';import{Membership,Pending}from'../../src/Screens';import '../../src/design.css';import '../../src/flows.css';import '../../src/screens.css';import '../../src/motion.css';import '../../src/typography.css';
function Fixture(){const [state,S]=useState('pending');const [notice,N]=useState('');const noop=()=>{};window.__auditSet=S;return <div className="phone-app" dir="rtl">{notice&&<p role="alert">{notice}</p>}{state==='pending'?<Pending back={noop} busy={false} refresh={()=>S('waiting')}/>:state==='app'?<main><h1>محاكاة الدخول للتطبيق</h1></main>:<Membership back={noop} active={state==='paid'} demo={false} price={state==='missing'?null:'SAR 55'} period={state==='missing'?undefined:'٣ أشهر'} status={state==='paid'?'paid':'free'} canStart={state!=='waiting'} canBuy={true} busy={false} buy={()=>{if(state==='fail')N('محاكاة فشل الشراء');else if(state==='cancel')N('محاكاة إلغاء الشراء');else S('paid')}} restore={()=>N('محاكاة استعادة المشتريات')} manage={()=>N('محاكاة إدارة الاشتراك')} refresh={()=>S('offer')} expiry={null} onPolicy={noop}/>} {state==='paid'&&<button onClick={()=>S('app')}>محاكاة الانتقال</button>}</div>};createRoot(document.getElementById('root')!).render(<Fixture/>);
